type DoctorCount = record(doctor: str, count: int)

fn count_by_doctor(appts: list<Appointment>) -> list<DoctorCount>
    let doctors = distinct(map(appts, a => a.doctor))
    return doctors |> map(d => DoctorCount(d, len(filter(appts, a => a.doctor == d))))

