type DaySummary = record(day: str, count: int, total_wait: int)

fn summarize_day(appointments: list<Appointment>, day: str) -> DaySummary
    let day_appointments = appointments |> filter(a => a.day == day)
    let count = len(day_appointments)
    let total_wait = sum(day_appointments, a => a.seen - a.start)
    return DaySummary(day, count, total_wait)

