type Appointment = record(patient: str, scheduled: int, seen: int)

fn average_wait(appts: list<Appointment>) -> dec
    let total = sum(appts, a => a.seen - a.scheduled)
    let n = len(appts)
    if n == 0
        return 0.0
    return dec(total) / dec(n)

