type Appointment = record(patient: str, doctor: str, day: int, arrival: int, start: int)
type DoctorLoad = record(doctor: str, count: int, total_wait: int)

fn wait(a: Appointment) -> int (start minus arrival if start is after arrival, otherwise 0)

fn doctor_load(appointments: list<Appointment>) -> list<DoctorLoad>
    let loads: list<DoctorLoad> = []
    for d in distinct(appointments, a => a.doctor)
        let group = appointments |> filter(a => a.doctor == d)
        let total_wait = group |> sum(a => wait(a))
        let count = len(group)
        push(loads, DoctorLoad(d, count, total_wait))
    return loads

